	border-top-width: 1pt;
	border-right-width: 1pt;
	border-bottom-width: 1pt;
	border-left-width: 1pt;
	font-family: -fm-font-family(HelveticaNeue,HelveticaNeue);
	color: rgba(15.6863%,15.6863%,15.6863%,1);
