	border-right-color: rgba(0%,56.8627%,80.7843%,1);
	border-bottom-color: rgba(0%,56.8627%,80.7843%,1);
	border-left-color: rgba(0%,56.8627%,80.7843%,1);
	box-shadow: none;
}
